func CalculateRouteCost(route Route, rates RateTable) (float64, error) {
	if len(route.Legs) == 0 {
		return 0, ErrEmptyRoute
	}
	var total float64
	for i, leg := range route.Legs {
		rate, ok := rates.PerKm[leg.VehicleClass]
		if !ok {
			return 0, fmt.Errorf("leg %d: no rate for vehicle class %q", i, leg.VehicleClass)
		}
		if leg.DistanceKm < 0 {
			return 0, fmt.Errorf("leg %d: negative distance", i)
		}
		total += leg.DistanceKm * rate
	}
	total += float64(len(route.Stops)) * rates.StopFee
	return total, nil
}


