pub enum UploadResult { Inserted(i64), Duplicate(i64) }

pub async fn record_upload(
    pool: &SqlitePool,
    sha256: &str,
    filename: &str,
    size_bytes: i64,
    taken_at: Option<&str>,
) -> sqlx::Result<UploadResult> {
    let mut tx = pool.begin().await?;

    let new_id: Option<i64> = sqlx::query_scalar(
        "INSERT INTO photos (sha256, filename, size_bytes, taken_at)
         VALUES (?1, ?2, ?3, ?4)
         ON CONFLICT(sha256) DO NOTHING
         RETURNING id",
    )
    .bind(sha256).bind(filename).bind(size_bytes).bind(taken_at)
    .fetch_optional(&mut *tx)
    .await?;

    let result = match new_id {
        Some(id) => UploadResult::Inserted(id),
        None => {
            let id: i64 = sqlx::query_scalar("SELECT id FROM photos WHERE sha256 = ?1")
                .bind(sha256)
                .fetch_one(&mut *tx)
                .await?;
            UploadResult::Duplicate(id)
        }
    };

    tx.commit().await?;
    Ok(result)
}


One caveat: the transaction only covers the DB. Write the file to a temp path first, then rename it into place only after `commit()` succeeds on an `Inserted` result.

Use an in-memory SQLite pool in the test and run your schema SQL against it. Cap it at one connection, because each connection to `sqlite::memory:` gets its own separate database.

rust
#[tokio::test]
async fn dupes_return_existing_id() {
    let pool = SqlitePoolOptions::new()
        .max_connections(1)
        .connect("sqlite::memory:").await.unwrap();
    sqlx::query(include_str!("../schema.sql")).execute(&pool).await.unwrap();

    let a = record_upload(&pool, "abc", "a.jpg", 10, None).await.unwrap();
    let b = record_upload(&pool, "abc", "b.jpg", 10, None).await.unwrap();
    assert!(matches!(a, UploadResult::Inserted(_)));
    assert!(matches!(b, UploadResult::Duplicate(_)));
}

