go
func (h *DispatchHandler) Handle(ctx context.Context, req DispatchRequest) error {
    route, err := h.store.LoadRoute(ctx, req.RouteID)
    if err != nil {
        return fmt.Errorf("dispatch: load route %s: %w", req.RouteID, err)
    }
    driver, err := h.assign(ctx, route)
    if err != nil {
        return fmt.Errorf("dispatch: assign driver for route %s: %w", route.ID, err)
    }
    if err := h.notifier.Send(ctx, driver.ID, route.ID); err != nil {
        return fmt.Errorf("dispatch: notify driver %s for route %s: %w", driver.ID, route.ID, err)
    }
    if err := h.store.MarkDispatched(ctx, route.ID, driver.ID); err != nil {
        return fmt.Errorf("dispatch: mark route %s dispatched: %w", route.ID, err)
    }
    return nil
}


The log-and-replace in the assign branch was throwing away the original error, so callers couldn't use `errors.Is`/`errors.As`. Logging can happen once at the top of the call chain instead. The notifier error is now returned. If a failed notification shouldn't block dispatch, we can handle it explicitly instead of dropping it.

