func (s *Store) queryRoute(ctx context.Context, id string) (*Route, error) {
    row := s.db.QueryRowContext(ctx, `SELECT id, origin, dest, status FROM routes WHERE id = $1`, id)
    var r Route
    if err := row.Scan(&r.ID, &r.Origin, &r.Dest, &r.Status); err != nil {
        return nil, err
    }
    return &r, nil
}

go
func (s *Store) queryRoute(ctx context.Context, id string) (*Route, error) {
    const q = `SELECT id, origin, dest, status FROM routes WHERE id = $1`
    var r Route
    err := s.withRetry(ctx, func(ctx context.Context) error {
        return s.db.QueryRowContext(ctx, q, id).Scan(&r.ID, &r.Origin, &r.Dest, &r.Status)
    })
    if errors.Is(err, sql.ErrNoRows) {
        return nil, fmt.Errorf("query route %s: %w", id, ErrRouteNotFound)
    }
    if err != nil {
        return nil, fmt.Errorf("query route %s: %w", id, err)
    }
    return &r, nil
}

func (s *Store) withRetry(ctx context.Context, fn func(context.Context) error) error {
    var err error
    for attempt := 0; attempt < 5; attempt++ {
        if err = fn(ctx); err == nil {
            return nil
        }
        var pgErr *pgconn.PgError
        if !errors.As(err, &pgErr) || pgErr.Code != "40001" {
            return err
        }
        select {
        case <-ctx.Done():
            return fmt.Errorf("retry aborted: %w", ctx.Err())
        case <-time.After(time.Duration(attempt+1) * 20 * time.Millisecond):
        }
    }
    return fmt.Errorf("retries exhausted: %w", err)
}


The query is plain SQL with `$1`, so it works on both databases. `withRetry` only retries `40001`, which Postgres rarely raises outside serializable transactions, so it's harmless there too. A single-row read like this rarely hits it, but the same helper will matter for the write paths. I assumed pgx for the driver, so adjust the `PgError` type if you use something else.

