func batchRoutes(stops []Stop, size int) [][]Stop {
    var out [][]Stop
    for i := 0; i < len(stops); i += size {
        var b []Stop
        for j := i; j < i+size && j < len(stops); j++ {
            if stops[j].Active {
                b = append(b, stops[j])
            }
        }
        out = append(out, b)
    }
    return out
}

Both `out` and every `b` grow from zero. Here's a version that preallocates both:

go
func batchRoutes(stops []Stop, size int) [][]Stop {
    if size <= 0 {
        return nil
    }
    out := make([][]Stop, 0, (len(stops)+size-1)/size)
    for i := 0; i < len(stops); i += size {
        end := min(i+size, len(stops))
        b := make([]Stop, 0, end-i)
        for _, s := range stops[i:end] {
            if s.Active {
                b = append(b, s)
            }
        }
        out = append(out, b)
    }
    return out
}

That's one allocation for `out` plus one per batch, and no regrowth. I also added a guard for `size <= 0`, since the original would loop forever on it.

