func BenchmarkBatchRoutes(b *testing.B) {
    for _, n := range []int{100, 1000, 10000} {
        stops := makeStops(n) // helper: mix of active/inactive
        b.Run(fmt.Sprintf("naive/n=%d", n), func(b *testing.B) {
            b.ReportAllocs()
            for i := 0; i < b.N; i++ {
                _ = batchRoutesNaive(stops, 50)
            }
        })
        b.Run(fmt.Sprintf("prealloc/n=%d", n), func(b *testing.B) {
            b.ReportAllocs()
            for i := 0; i < b.N; i++ {
                _ = batchRoutes(stops, 50)
            }
        })
    }
}

